{
  "name": "Job Description Creation and Approval Process",
  "resources": [
    {
      "name": "HR Clerk",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Department",
      "capacity": 1,
      "resource_type": "department"
    }
  ],
  "events": [
    {
      "id": "start_event",
      "name": "Vacancy reported",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Vacancy Report"
    },
    {
      "id": "end_clarification_sent",
      "name": "Clarification requested",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Clarification Request"
    },
    {
      "id": "end_job_posted",
      "name": "Job posted successfully",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "start_dept",
      "name": "Job description received for review",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Job Description"
    },
    {
      "id": "end_dept_approved",
      "name": "Approval sent",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Approval Notification"
    },
    {
      "id": "end_dept_rejected",
      "name": "Rejection and correction request sent",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Rejection & Correction Request"
    }
  ],
  "tasks": [
    {
      "id": "task_create_jd",
      "name": "Create job description",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "HR Clerk",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": [
        "data_job_description"
      ]
    },
    {
      "id": "task_ask_dept",
      "name": "Ask Department for clarification",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "HR Clerk",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_submit_jd",
      "name": "Submit job description for consideration",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "HR Clerk",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_job_description"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_correct_jd",
      "name": "Correct job description",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "HR Clerk",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_job_description"
      ],
      "output_data_ids": [
        "data_job_description"
      ]
    },
    {
      "id": "task_post_job",
      "name": "Post the job",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "HR Clerk",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_job_description"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_review_jd",
      "name": "Consider and review job description",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_job_description"
      ],
      "output_data_ids": []
    }
  ],
  "gateways": [
    {
      "id": "gw_confusion",
      "name": "Is there confusion in the message?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_to_ask",
          "condition": "Yes"
        },
        {
          "flow_id": "flow_to_submit",
          "condition": "No"
        }
      ]
    },
    {
      "id": "gw_approval_outcome",
      "name": "Is job description approved?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_approved",
          "condition": "Approved"
        },
        {
          "flow_id": "flow_rejected",
          "condition": "Rejected"
        }
      ]
    },
    {
      "id": "gw_dept_decision",
      "name": "Department decision?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_dept_approve",
          "condition": "Approve"
        },
        {
          "flow_id": "flow_dept_reject",
          "condition": "Reject"
        }
      ]
    }
  ],
  "sequence_flows": [
    {
      "id": "flow_1",
      "source_id": "start_event",
      "target_id": "task_create_jd",
      "condition_name": null
    },
    {
      "id": "flow_2",
      "source_id": "task_create_jd",
      "target_id": "gw_confusion",
      "condition_name": null
    },
    {
      "id": "flow_to_ask",
      "source_id": "gw_confusion",
      "target_id": "task_ask_dept",
      "condition_name": "Yes"
    },
    {
      "id": "flow_to_submit",
      "source_id": "gw_confusion",
      "target_id": "task_submit_jd",
      "condition_name": "No"
    },
    {
      "id": "flow_3",
      "source_id": "task_ask_dept",
      "target_id": "end_clarification_sent",
      "condition_name": null
    },
    {
      "id": "flow_4",
      "source_id": "task_submit_jd",
      "target_id": "gw_approval_outcome",
      "condition_name": null
    },
    {
      "id": "flow_approved",
      "source_id": "gw_approval_outcome",
      "target_id": "task_post_job",
      "condition_name": "Approved"
    },
    {
      "id": "flow_rejected",
      "source_id": "gw_approval_outcome",
      "target_id": "task_correct_jd",
      "condition_name": "Rejected"
    },
    {
      "id": "flow_5",
      "source_id": "task_correct_jd",
      "target_id": "task_submit_jd",
      "condition_name": null
    },
    {
      "id": "flow_6",
      "source_id": "task_post_job",
      "target_id": "end_job_posted",
      "condition_name": null
    },
    {
      "id": "flow_dept_1",
      "source_id": "start_dept",
      "target_id": "task_review_jd",
      "condition_name": null
    },
    {
      "id": "flow_dept_2",
      "source_id": "task_review_jd",
      "target_id": "gw_dept_decision",
      "condition_name": null
    },
    {
      "id": "flow_dept_approve",
      "source_id": "gw_dept_decision",
      "target_id": "end_dept_approved",
      "condition_name": "Approve"
    },
    {
      "id": "flow_dept_reject",
      "source_id": "gw_dept_decision",
      "target_id": "end_dept_rejected",
      "condition_name": "Reject"
    }
  ],
  "pools": [
    {
      "id": "pool_hr",
      "name": "HR Clerk",
      "element_ids": [
        "start_event",
        "end_clarification_sent",
        "end_job_posted",
        "task_create_jd",
        "task_ask_dept",
        "task_submit_jd",
        "task_correct_jd",
        "task_post_job",
        "gw_confusion",
        "gw_approval_outcome"
      ]
    },
    {
      "id": "pool_department",
      "name": "Department",
      "element_ids": [
        "start_dept",
        "end_dept_approved",
        "end_dept_rejected",
        "task_review_jd",
        "gw_dept_decision"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "msg_submit_jd",
      "source_id": "task_submit_jd",
      "target_id": "start_dept",
      "name": "Job Description for Consideration"
    },
    {
      "id": "msg_approval_resp",
      "source_id": "end_dept_approved",
      "target_id": "gw_approval_outcome",
      "name": "Approval Notification"
    },
    {
      "id": "msg_rejection_resp",
      "source_id": "end_dept_rejected",
      "target_id": "gw_approval_outcome",
      "name": "Rejection & Correction Request"
    }
  ],
  "data_objects": [
    {
      "id": "data_job_description",
      "name": "Job Description"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
